/**
 * The API's types: one alias per schema of the server's OpenAPI document (`schema.d.ts`, generated by `pnpm api` from
 * `crates/server/openapi.json`), so the app names them as `crates/core` does. Only the event helpers below are
 * derived here. A field the server may leave empty is optional and nullable in the schema (`x?: T | null`): test it
 * with `== null`.
 */
import type { components } from "./schema";

type Schemas = components["schemas"];

/** A value for each side. */
export interface SidePair<T> {
  white: T;
  black: T;
}

/** Each event kind with its payload, read from the `EventData` union. */
export type EventPayloads = { [E in Schemas["EventData"] as E["kind"]]: E["data"] };
export type EventKind = keyof EventPayloads;
/** One event of the stream: `{ id, topic, kind, data }`, narrowed by `kind`. */
export type AppEvent = { [K in EventKind]: { id: number; topic: string; kind: K; data: EventPayloads[K] } }[EventKind];

/** A row of the comparison that has a leader. */
export type LeaderRow = Schemas["Leader"]["row"];

